<template>
  <div
    class="f-toggle"
    :class="[
      { 'f-toggle--active': isActive, 'f-toggle--disabled': disable, 'f-toggle--left-label': leftLabel },
      sizeClass
    ]"
    @click="toggle"
  >
    <span v-if="label && leftLabel" class="f-toggle__label">{{ label }}</span>
    <div class="f-toggle__track">
      <div class="f-toggle__thumb"></div>
    </div>
    <span v-if="label && !leftLabel" class="f-toggle__label">{{ label }}</span>
    <slot></slot>
  </div>
</template>

<script>
import { defineComponent, computed } from 'vue'
import { toBoolPreference } from 'src/utils/preferenceBool'

export default defineComponent({
  name: 'FellowToggle',
  props: {
    modelValue: {
      // Accepts the raw preference value (boolean, or string/number from the
      // settings store). String is declared BEFORE Boolean so Vue does not
      // cast an empty string "" to `true` (its boolean-attribute rule); the
      // value is normalised explicitly via toBoolPreference / isActive.
      type: [String, Boolean, Number],
      default: false
    },
    label: {
      type: String,
      default: ''
    },
    disable: {
      type: Boolean,
      default: false
    },
    size: {
      type: String,
      default: 'md',
      validator: (value) => ['xs', 'sm', 'md', 'lg'].includes(value)
    },
    leftLabel: {
      type: Boolean,
      default: false
    }
  },
  emits: ['update:modelValue'],
  setup(props, { emit }) {
    const sizeClass = computed(() => `f-toggle--${props.size}`)
    // Normalised on/off state — drives both the rendered class and the value
    // emitted on click, so a string "0" renders OFF and clicking it emits a
    // real boolean `true` (DRFS-626).
    const isActive = computed(() => toBoolPreference(props.modelValue))

    const toggle = () => {
      if (!props.disable) {
        emit('update:modelValue', !isActive.value)
      }
    }

    return {
      sizeClass,
      isActive,
      toggle
    }
  }
})
</script>

